#include <iostream>
#include <string>
using namespace std;
​
int main() {

    string input;

    getline(cin, input);

    int len = input.size();
    // 统计o出现的数量
    int num = 0;
    // 遍历字符串，统计'o'字符的数量
    for (char chr : input) {
        if (chr == 'o') {
            num += 1;
        }
    }
    // 如果'o'字符出现的次数是偶数，则输出字符串的长度
    if (num % 2 == 0) {
        cout << len << endl;
    } else {
        // 如果'o'字符出现的次数是奇数，则输出字符串长度减1
        cout << len - 1 << endl;
    }
    return 0;
}

