const readline = require('readline');
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
// 读取整行输入
rl.on('line', (input) => {
    let len = input.length;
    let num = (input.match(/o/g) || []).length; // 统计 'o' 出现的次数
​
    // 根据 'o' 的数量判断输出值
    console.log(num % 2 === 0 ? len : len - 1);

    rl.close();
});
