package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
func main() {

    reader := bufio.NewReader(os.Stdin)
    input, _ := reader.ReadString('\n') // 读取整行输入
    input = strings.TrimSpace(input)    // 去掉首尾空白字符
​
    lenStr := len(input)
    num := strings.Count(input, "o") // 统计 'o' 出现的次数
​
    // 根据 'o' 的数量判断输出值
    if num%2 == 0 {
        fmt.Println(lenStr)
    } else {
        fmt.Println(lenStr - 1)
    }
}
